# Generated by qa-agent from cases/bookings.yaml. Do not edit: change the cases, then run qa-agent generate.
"""Bookings: 1 case, one test each."""

import pytest

from api_test_framework import Expect, unique_id


@pytest.mark.functional
@pytest.mark.smoke
@pytest.mark.writes
@pytest.mark.case("TC001")
@pytest.mark.priority("P1")
def test_tc001_a_new_booking_can_be_read_back_by_its_pnr(api, context):
    """A new booking can be read back by its PNR. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Asha Rao {unique}",
        "email": f"asha.{unique}@testdata.example",
        "amount": 250,
    })
    Expect(response).status_is(201).field_equals("status", "active")
    context.remember("pnr", response.value("pnr"))
    # 2. GET /bookings/{{pnr}}
    response = api.get(f"/bookings/{context.get('pnr')}")
    Expect(response).status_is(200).field_equals("pnr", context.get("pnr")).field_equals("amount", 250)
